// ── 9. 无状态 idle：无 running 记录时 idle 不误报 ──
describe("无状态 idle 不误报", () => {
  it("无 running 记录的 idle 不通知", async () => {
    const infos = [];
    const { listeners } = await makeNotifier(work, { historyFile: join(work, "noop-idle-hist.jsonl") }, {
      logger: { warn: () => {}, info: (t) => infos.push(t) },
