/**
 * dsh-notifier — unit：存储域工厂直测（L1 层内直测补盲）。
 *
 * 覆盖存储域工厂直测：history 写队列串行化/原子写（tmp+rename）/
 * 滚动上限/按天清理/失败 warn；status 内存镜像/failStreak/64 条上限/debounce
 * 落盘/冷启动懒加载/错误摘要截断。工厂不在包导出面（导出面零 diff 约束），
 * 直测本域 interface.ts（Node strip-types 原生执行）。
 */
import { readFileSync, writeFileSync, mkdtempSync, rmSync, readdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createHistoryStore, createStatusStore, HISTORY_LIMIT } from "../../src/stores/interface.ts";

/** 轮询文件直到谓词成立或超时（写队列 fire-and-forget，固定 sleep 会 flake）。 */
async function pollFile(file: string, predicate: (text: string) => boolean, timeoutMs = 2000) {
  const start = Date.now();
  for (;;) {
    try {
      const text = readFileSync(file, "utf8");
      if (predicate(text)) return text;
    } catch {
      // 文件尚未出现
    }
    if (Date.now() - start > timeoutMs) {
      throw new Error(`轮询超时等待 ${file}`);
    }
    await new Promise((resolve) => setTimeout(resolve, 15));
  }
}

let work: string;
beforeAll(() => {
  work = mkdtempSync(join(tmpdir(), "dnotify-unit-stores-"));
});
afterAll(() => {
  rmSync(work, { recursive: true, force: true });
});

describe("history 写队列串行化 + 原子写（并发 append 不丢记录、无 tmp 残留）", () => {
  let lines: string[];
  let leftovers: string[];

  beforeAll(async () => {
    const file = join(work, "hist-1.jsonl");
    rmSync(file, { force: true });
    const warns: string[] = [];
    const store = createHistoryStore({ file, maxAgeDays: () => 0, warn: (m) => warns.push(m) });
    // 并发 fire-and-forget 追加 20 条：写队列串行化保证全部落盘
    for (let i = 0; i < 20; i += 1) store.append({ ts: 1000 + i, kind: "done", title: `t${i}`, message: `m${i}` });
    const text = await pollFile(file, (t) => t.trim().split("\n").length === 20);
    lines = text.trim().split("\n");
    leftovers = readdirSync(work).filter((f) => f.includes(".tmp"));
  });

  it("并发 append 20 条全部落盘（写队列串行化不丢记录）", () => {
    expect(lines.length).toBe(20);
  });

  it("每行均为合法 jsonl", () => {
    for (const line of lines) expect(JSON.parse(line).ts >= 1000).toBeTruthy();
  });

  it("tmp+rename 原子写无残留临时文件", () => {
    expect(leftovers.length).toBe(0);
  });
});

describe("滚动上限（写侧与读侧都只保留最近 HISTORY_LIMIT 条）", () => {
  let text: string;
  let records: Awaited<ReturnType<ReturnType<typeof createHistoryStore>["read"]>>;

  beforeAll(async () => {
    const file = join(work, "hist-2.jsonl");
    // 预置 2*HISTORY_LIMIT 条，单次 append 即越过写侧截断阈值（lines.length > HISTORY_LIMIT*2）：
    // 原写法连续 append 250 次只为命中外层读侧上限，250 次「全文件读-改-写-rename」的
    // I/O 突发在 CI 上会累积超过 2s 轮询预算（实测两处独立 CI job 同时超时），且写侧
    // 截断分支从未被触及。预置后写侧与读侧上限都由一次 append 决定性地验证。
    const seeded = Array.from({ length: HISTORY_LIMIT * 2 }, (_, i) =>
      JSON.stringify({ ts: i, kind: "done", title: "t", message: `m${i}` }));
    writeFileSync(file, `${seeded.join("\n")}\n`, "utf8");

    const store = createHistoryStore({ file, maxAgeDays: () => 0, warn: () => {} });
    store.append({ ts: 9999, kind: "done", title: "t", message: "fresh" });

    text = await pollFile(file, (t) => t.includes("fresh"));
    records = await store.read();
  });

  it("写侧截断到最近 HISTORY_LIMIT 条", () => {
    expect(text.trim().split("\n").filter(Boolean).length).toBe(HISTORY_LIMIT);
  });

  it("read 只返回最近 HISTORY_LIMIT 条", () => {
    expect(records.length).toBe(HISTORY_LIMIT);
  });

  it("保留的是最新记录", () => {
    expect(records[records.length - 1].message).toBe("fresh");
  });

  it("最旧记录已被挤出滚动窗口", () => {
    expect(records[0].message).toBe(`m${HISTORY_LIMIT + 1}`);
  });
});

describe("按天自动清理（maxAgeDays 实时读取器）", () => {
  let records: Awaited<ReturnType<ReturnType<typeof createHistoryStore>["read"]>>;

  beforeAll(async () => {
    const file = join(work, "hist-3.jsonl");
    rmSync(file, { force: true });
    let keepDays = 0;
    const store = createHistoryStore({ file, maxAgeDays: () => keepDays, warn: () => {} });
    store.append({ ts: Date.now() - 30 * 86400000, kind: "done", title: "old", message: "超期" });
    store.append({ ts: Date.now(), kind: "done", title: "new", message: "最新" });
    await pollFile(file, (t) => t.trim().split("\n").length === 2);
    keepDays = 7; // 打开按天清理（热更新即时生效）
    store.append({ ts: Date.now(), kind: "done", title: "new2", message: "再写一条触发清理" });
    await pollFile(file, (t) => {
      try {
        const lines = t.trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
        return lines.length === 2 && lines.every((l) => l.message !== "超期");
      } catch {
        return false;
      }
    });
    records = await store.read();
  });

  it("超期记录被清理，仅剩两条新记录", () => {
    expect(records.length).toBe(2);
  });

  it("30 天前记录已剔除", () => {
    expect(records.every((r) => r.message !== "超期")).toBeTruthy();
  });
});

describe("写入失败 → warn 不抛（fire-and-forget 铁律）", () => {
  let warns: string[];

  beforeAll(async () => {
    const file = join(work, "hist-4", "nested", "hist.jsonl"); // 父目录不存在 → 写入必失败
    warns = [];
    const store = createHistoryStore({ file, maxAgeDays: () => 0, warn: (m) => warns.push(m) });
    store.append({ ts: 1, kind: "done", title: "t", message: "m" });
    // 轮询等写链的失败回调落地：固定 sleep 在 CI 慢机会在 warn 到达前断言（防 flake 纪律）
    const warnDeadline = Date.now() + 2000;
    while (warns.length === 0 && Date.now() < warnDeadline) {
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
  });

  it("写入失败仅 warn（不阻塞通知主流程）", () => {
    expect(warns.length).toBe(1);
  });

  it("warn 带失败上下文", () => {
    expect(warns[0].includes("历史记录写入失败")).toBeTruthy();
  });
});

// 原脚本块是「动作 → 断言 → 新动作 → 新断言」交错序列：按交错点拆四个 describe，
// 每个 describe 内只有一段动作序列，断言不再观察到后续动作改写过的状态。
describe("status 内存镜像 / failStreak / 错误摘要截断", () => {
  let snap: Awaited<ReturnType<ReturnType<typeof createStatusStore>["read"]>>;

  beforeAll(async () => {
    const file = join(work, "status-1.json");
    rmSync(file, { force: true });
    const store = createStatusStore({ file, warn: () => {} });
    store.record("bark:a", "failed", "x".repeat(500));
    store.record("bark:a", "failed", "again");
    store.record("bark:a", "ok");
    store.record("webhook:b", "failed", "err");
    snap = await store.read();
  });

  it("内存镜像立即更新", () => {
    expect(snap["bark:a"].lastStatus).toBe("ok");
  });

  it("成功清零连续失败计数", () => {
    expect(snap["bark:a"].failStreak).toBe(0);
  });

  it("失败递增连续计数", () => {
    expect(snap["webhook:b"].failStreak).toBe(1);
  });

  it("错误摘要记录", () => {
    expect(snap["webhook:b"].lastError).toBe("err");
  });
});

describe("status debounce 落盘", () => {
  let persisted: Record<string, { lastStatus: string }>;

  beforeAll(async () => {
    const file = join(work, "status-2.json");
    rmSync(file, { force: true });
    const store = createStatusStore({ file, warn: () => {} });
    store.record("bark:a", "failed", "x".repeat(500));
    store.record("bark:a", "failed", "again");
    store.record("bark:a", "ok");
    store.record("webhook:b", "failed", "err");
    // debounce 落盘（轮询等待，防固定 sleep flake）
    const text = await pollFile(file, (t) => t.includes("bark:a"));
    persisted = JSON.parse(text);
  });

  it("debounce 合并后落盘反映最新终态", () => {
    expect(persisted["bark:a"].lastStatus).toBe("ok");
  });
});

describe("status 64 条上限（最旧先出）", () => {
  let after: Awaited<ReturnType<ReturnType<typeof createStatusStore>["read"]>>;

  beforeAll(async () => {
    const file = join(work, "status-3.json");
    rmSync(file, { force: true });
    const store = createStatusStore({ file, warn: () => {} });
    store.record("bark:a", "failed", "x".repeat(500));
    store.record("bark:a", "failed", "again");
    store.record("bark:a", "ok");
    store.record("webhook:b", "failed", "err");
    for (let i = 0; i < 70; i += 1) store.record(`ch:${i}`, "ok");
    after = await store.read();
  });

  it("状态条目上限 64（防已删频道残留键累积）", () => {
    expect(Object.keys(after).length).toBe(64);
  });

  it("最近频道保留", () => {
    expect(after["ch:69"].lastStatus).toBe("ok");
  });

  it("最旧条目被逐出", () => {
    expect(!after["webhook:b"]).toBeTruthy();
  });
});

describe("status 冷启动懒加载", () => {
  let restored: Awaited<ReturnType<ReturnType<typeof createStatusStore>["read"]>>;

  beforeAll(async () => {
    const file = join(work, "status-4.json");
    rmSync(file, { force: true });
    const store = createStatusStore({ file, warn: () => {} });
    store.record("bark:a", "failed", "x".repeat(500));
    store.record("bark:a", "failed", "again");
    store.record("bark:a", "ok");
    store.record("webhook:b", "failed", "err");
    for (let i = 0; i < 70; i += 1) store.record(`ch:${i}`, "ok");
    await store.read();
    // 等 debounce 落盘含 ch:69 后新建 store 从文件恢复
    await pollFile(file, (t) => t.includes("ch:69"));
    const store2 = createStatusStore({ file, warn: () => {} });
    restored = await store2.read();
  });

  it("冷启动从文件恢复内存镜像", () => {
    expect(restored["ch:69"].lastStatus).toBe("ok");
  });
});

