  it("解包重包后 ask 返回值不变，this 绑定正确", async () => {
    expect((await rewrapped()).result2).toEqual({ answers: ["svc-marker"] });
  });

  it("解包重包不叠层，通知只发一次", async () => {
    const r = await rewrapped();
    expect(r.f.infos.length).toBe(r.infoCountBefore + 1);
  });
});

