// @ts-nocheck（e2e/集成面类型化技术债：桩对象密集，暂不参与 test/tsconfig 编译）
/**
 * dsh-notifier — e2e（提交后置三态 / 聚合批处理域）：开关禁用时的三态提交、
 * 免打扰拦截后的同 turn 去重、批次按「入队成功」提交、flush 时序不回退。
 *
 * 拆法：原 e2e-done.test.ts 的块 7（B-1 开关禁用三态）、块 8（B-2 免打扰）、
 * 块 9（B-4 入队即提交）、块 10（B-4 flush 时序）落在此文件。
 *
 * 迁移说明：每块都是「动作 → 累计计数断言 → 新动作 → 断言」的交错序列，
 * 故整体执行一次并物化各检查点计数（同 turn 再现 idle 前后、flush 前后），
 * 用例只读快照。
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { makeNotifier, agentWithTitle, turnPair, waitMergeWindow, waitForHistory, quietWindowNow } from "../helpers.ts";
import { ROUTES } from "../../src/index.ts";

let work: string;
beforeAll(() => {
  work = mkdtempSync(join(tmpdir(), "dnotify-e2e-done-commit-"));
});
afterAll(() => {
  rmSync(work, { recursive: true, force: true });
});

/** 带 info 收集的 logger 覆盖。 */
function loggingOverride(infos) {
  return { logger: { warn: () => {}, info: (t) => infos.push(t) } };
}

// 开关禁用三态提交——notifyTaskDone=false 时 completed idle 不通知，
// 但 lastEndedTurn 照常提交，同 turn 再现 idle 不重复处理。
describe("B-1：notifyTaskDone=false 的三态提交", () => {
  let infos: string[];
  let warns: string[];
  let c: { afterPair: number; afterRepeat: number };

  beforeAll(async () => {
    infos = [];
    warns = [];
    const { listeners } = await makeNotifier(work, { doneMergeWindowMs: 0, notifyTaskDone: false }, { logger: { info: (t) => infos.push(t), warn: (t) => warns.push(t) } });
    const status = listeners.get("agent/status")[0];
    const pair = turnPair("b1-1", "开关禁用任务", {}, { turn: 1 });
    status({ agent: pair.running, status: "running" });
    status({ agent: pair.idle, status: "idle" });
    const afterPair = infos.filter((t) => /: done /.test(t)).length;
    // 同 turn 再现 idle：lastEndedTurn 已提交 → 无新证据 → skip（不重复处理）；
    // 构造为「events 仍停 turn=1」的 abort-early 形态（快照 ≤ running 基线冻结）
    status({ agent: agentWithTitle("b1-1", "开关禁用任务", { turnEnd: 1 }), status: "running" });
    status({ agent: agentWithTitle("b1-1", "开关禁用任务", { turnEnd: 1 }), status: "idle" });
    c = { afterPair, afterRepeat: infos.filter((t) => /: done /.test(t)).length };
  });

  it("B-1：notifyTaskDone=false 主任务不通知", () => {
    expect(c.afterPair).toBe(0);
  });

  it("B-1：开关禁用后同 turn 再现 idle 不重复", () => {
    expect(c.afterRepeat).toBe(0);
  });

  it("B-1：再现 idle 走跳过路径 warn 留痕", () => {
    expect(warns.some((t) => t.includes("b1-1") && /完成判定跳过/.test(t))).toBeTruthy();
  });
});

// 免打扰拦截后同 turn 再现 idle 不重复——quietHours 命中且 done 不在
// allowKinds 时，idle completed → 仅一条 suppressed 历史、无系统通知；
// 同 turn 再现 idle → 不重复通知、不新增记录。
describe("B-2：免打扰拦截后同 turn 再现 idle 不重复", () => {
  let infos: string[];
  let records: Array<Record<string, unknown>>;
  let after: Array<Record<string, unknown>>;

  beforeAll(async () => {
    // 动态窗口：写死 "00:00"/"23:59" 在半开区间镜下 23:59 这一分钟不命中
    // （UTC 边缘必炸，run 33282203798 根因）；围绕当前时间 ±2 分钟恒命中。
    const qhAll = quietWindowNow();
    infos = [];
    const { listeners, routes } = await makeNotifier(work, { doneMergeWindowMs: 0, quietHours: { ...qhAll, allowKinds: ["ask"] }, historyFile: join(work, "b2-hist.jsonl") }, loggingOverride(infos));
    const status = listeners.get("agent/status")[0];
    const historyRoute = routes.find((r) => r.path === ROUTES.history);
    const pair = turnPair("b2-1", "免打扰完成", {}, { turn: 1 });
    status({ agent: pair.running, status: "running" });
    status({ agent: pair.idle, status: "idle" });
    records = await waitForHistory(historyRoute, (r) => r.some((e) => e.kind === "done" && e.suppressed === "quiet"));
    // 同 turn 再现 idle：免打扰拦截也是三态提交之一（lastEndedTurn 已推进）→ 不重复
    status({ agent: agentWithTitle("b2-1", "免打扰完成", { turnEnd: 1 }), status: "running" });
    status({ agent: agentWithTitle("b2-1", "免打扰完成", { turnEnd: 1 }), status: "idle" });
    after = await waitForHistory(historyRoute, (r) => r.length > records.length, 500);
  });

  it("B-2：免打扰拦截不发出系统通知", () => {
    expect(!infos.some((t) => /dsh-notifier: done /.test(t) && !t.includes("被免打扰拦截"))).toBeTruthy();
  });

  it("B-2：拦截记录日志", () => {
    expect(infos.some((t) => t.includes("被免打扰拦截"))).toBeTruthy();
  });

  it("B-2：仅一条 suppressed:quiet 历史", () => {
    expect(records.filter((e) => e.kind === "done" && e.suppressed === "quiet").length).toBe(1);
  });

  it("B-2：同 turn 再现 idle 不新增历史记录", () => {
    expect(after.length).toBe(records.length);
  });
});

// 批次按「入队成功」提交、与聚合 flush 成败解耦——doneMergeWindowMs>0
// 时首条完成入队即推进 lastEndedTurn（窗口内同 turn 再现不重复）。
describe("B-4：入队即提交（窗口内同 turn 再现 idle 不重复）", () => {
  let infos: string[];
  let c: { afterPair: number; afterRepeat: number };

  beforeAll(async () => {
    infos = [];
    const { listeners } = await makeNotifier(work, { doneMergeWindowMs: 5000 }, loggingOverride(infos));
    const status = listeners.get("agent/status")[0];
    const pair = turnPair("b4-1", "合并窗口任务", {}, { turn: 1 });
    status({ agent: pair.running, status: "running" });
    status({ agent: pair.idle, status: "idle" });
    const afterPair = infos.filter((t) => /: done /.test(t)).length;
    // 窗口未 flush 时同 turn 再现 idle：入队成功已提交 lastEndedTurn → 不重复
    status({ agent: agentWithTitle("b4-1", "合并窗口任务", { turnEnd: 1 }), status: "running" });
    status({ agent: agentWithTitle("b4-1", "合并窗口任务", { turnEnd: 1 }), status: "idle" });
    c = { afterPair, afterRepeat: infos.filter((t) => /: done /.test(t)).length };
  });

  it("B-4：首条完成即时通知并入队", () => {
    expect(c.afterPair).toBe(1);
  });

  it("B-4：窗口内同 turn 再现 idle 不重复（入队即提交）", () => {
    expect(c.afterRepeat).toBe(1);
  });
});

// flush 时序：首条入队即提交（不依赖 flush 结果）——窗口到点正常 flush
// 补发聚合条后，已提交 turn 不回退（再现 idle 不重复）。
// （「flush 阶段 notify 抛错」路径为产品 setTimeout 异步回调的既有行为，
// 触发会 uncaught、使 Stryker 测试宿主判 Error（vitest runner 下 uncaught 计入
// errorsSet），故以「提交点先于 flush」的时序验证覆盖。）
describe("B-4：flush 补发聚合条且已提交 turn 不回退", () => {
  let infos: string[];
  let c: { windowed: number; flushed: number; afterRepeat: number };

  beforeAll(async () => {
    infos = [];
    const { listeners } = await makeNotifier(work, { doneMergeWindowMs: 30 }, loggingOverride(infos));
    const status = listeners.get("agent/status")[0];
    const doneCount = () => infos.filter((t) => /: done /.test(t)).length;
    const pairA = () => turnPair("b4f-a", "flush 后 A", {}, { turn: 1 });
    const pairB = () => turnPair("b4f-b", "flush 后 B", {}, { turn: 1 });
    // 两条完成进入同一聚合窗口（首条即时、第二条入队挂起）
    status({ agent: pairA().running, status: "running" });
    status({ agent: pairA().idle, status: "idle" });
    status({ agent: pairB().running, status: "running" });
    status({ agent: pairB().idle, status: "idle" });
    const windowed = doneCount();
    // 等窗口到点：flush 补发聚合条（正常路径；短窗 30ms 已注入）
    await waitMergeWindow(30);
    const flushed = doneCount();
    // 已提交 turn 不回退：flush 完成后再现 idle（无新 closure 形态）不重复
    status({ agent: agentWithTitle("b4f-a", "flush 后 A", { turnEnd: 1 }), status: "running" });
    status({ agent: agentWithTitle("b4f-a", "flush 后 A", { turnEnd: 1 }), status: "idle" });
    status({ agent: agentWithTitle("b4f-b", "flush 后 B", { turnEnd: 1 }), status: "running" });
    status({ agent: agentWithTitle("b4f-b", "flush 后 B", { turnEnd: 1 }), status: "idle" });
    c = { windowed, flushed, afterRepeat: doneCount() };
  });

  it("B-4：窗口内首条即时、第二条挂起", () => {
    expect(c.windowed).toBe(1);
  });

  it("B-4：flush 补发聚合条", () => {
    expect(c.flushed).toBe(2);
  });

  it("B-4：聚合条文案带计数", () => {
    expect(infos.some((t) => /: done /.test(t) && t.includes("另有 1 个任务已完成"))).toBeTruthy();
  });

  it("B-4：flush 后已提交 turn 不回退重发", () => {
    expect(c.afterRepeat).toBe(2);
  });
});

// @ts-nocheck（e2e/集成面类型化技术债：桩对象密集，暂不参与 test/tsconfig 编译）
/**
 * dsh-notifier — e2e：审批请求通知（approval/request waterfall）。
 *
 * 覆盖：五个事件监听器注册面；审批通知（工具中文名/任务标题/申请理由/
 * 行动建议，不短路、不暴露会话 id）；无标题降级；next 抛错原样传播；
 * notifyAsk=false 不通知；免打扰紧急例外 allowKinds。
 */
import { join } from "node:path";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { makeNotifier, agentWithTitle } from "../helpers.ts";

/** 带 info 收集的 logger 覆盖。 */
function loggingOverride(infos) {
  return { logger: { warn: () => {}, info: (t) => infos.push(t) } };
}

let work: string;
beforeAll(() => {
  work = mkdtempSync(join(tmpdir(), "dnotify-e2e-approval-"));
});
afterAll(() => {
  rmSync(work, { recursive: true, force: true });
});

/** 审批夹具：独立 history 文件 + info 收集 + approval/request 监听器。 */
async function approvalNotifier(tag, config = {}) {
  const infos = [];
  const { listeners } = await makeNotifier(work, { historyFile: join(work, `history-ap-${tag}.jsonl`), ...config }, loggingOverride(infos));
  return { infos, listeners, approval: listeners.get("approval/request")[0] };
}

/** 主流程审批请求（带标题/工具/理由）。 */
const req = () => ({ toolName: "pwsh", agent: agentWithTitle("session-1", "优化 notifier 插件"), reason: "escalate sandbox to workspace-write: 需要写文件", signal: { aborted: false } });
/** 无会话标题的审批请求（降级为仅工具名）。 */
const reqNoTitle = () => ({ toolName: "bash", agent: agentWithTitle("session-9", null) });

describe("监听器注册面", () => {
  it("五个事件监听器已注册", async () => {
    const { listeners } = await approvalNotifier("reg");
    const approval = listeners.get("approval/request")[0];
    const status = listeners.get("agent/status")[0];
    const error = listeners.get("agent/error")[0];
    const turnStop = listeners.get("agent/turn-stopping")[0];
    const disposed = listeners.get("agent/disposed")[0];
    expect(approval && status && error && turnStop && disposed).toBeTruthy();
  });

  it("不再挂 pre-execute（真实审批走 approval/request）", async () => {
    const { listeners } = await approvalNotifier("reg");
    expect(listeners.has("tools/pre-execute")).toBe(false);
  });
});

describe("批准通知主流程（工具中文名 / 任务标题 / 申请理由 / 行动建议）", () => {
  // approval/request：通知后不短路返回 next 结果
  async function firstApproval() {
    const f = await approvalNotifier("main");
    const outcome = await f.approval(req(), async () => "allowed-once");
    return { ...f, outcome };
  }

  it("不短路，返回 next 结果", async () => {
    expect((await firstApproval()).outcome).toBe("allowed-once");
  });

  it("通知只发一条", async () => {
    expect((await firstApproval()).infos.length).toBe(1);
  });

  it("通知含 ask kind", async () => {
    expect((await firstApproval()).infos[0]).toMatch(/ask/);
  });

  it("审批通知带任务标题与工具中文名", async () => {
    expect((await firstApproval()).infos[0]).toMatch(/任务「优化 notifier 插件」等待审批（工具「PowerShell 命令」）/);
  });

  it("审批通知带申请理由", async () => {
    expect((await firstApproval()).infos[0]).toMatch(/理由：escalate sandbox to workspace-write: 需要写文件/);
  });

  it("审批通知带行动建议", async () => {
    expect((await firstApproval()).infos[0]).toMatch(/确认或拒绝/);
  });

  it("审批通知不暴露内部会话 id", async () => {
    expect((await firstApproval()).infos[0].includes("session-")).toBe(false);
  });
});

describe("无会话标题：降级为仅工具名", () => {
  async function secondApproval() {
    const f = await approvalNotifier("notitle");
    await f.approval(req(), async () => "allowed-once");
    const outcome2 = await f.approval(reqNoTitle(), async () => "allowed-once");
    return { ...f, outcome2 };
  }

  it("不短路，返回 next 结果（无标题路径）", async () => {
    expect((await secondApproval()).outcome2).toBe("allowed-once");
  });

  it("无标题时仅显示工具中文名", async () => {
    expect((await secondApproval()).infos[1]).toMatch(/工具「终端命令」等待审批/);
  });

  it("无标题时不显示任务行", async () => {
    expect((await secondApproval()).infos[1].includes("任务「")).toBe(false);
  });

  it("无标题路径也不暴露会话 id", async () => {
    expect((await secondApproval()).infos[1].includes("session-9")).toBe(false);
  });
});

describe("next 抛错 → 原样传播（waterfall 兜底由上层负责）", () => {
  async function throwingApproval() {
    const f = await approvalNotifier("throw");
    await f.approval(req(), async () => "allowed-once");
    await f.approval(reqNoTitle(), async () => "allowed-once");
    const failing = () => f.approval(req(), async () => {
      throw new Error("boom");
    });
    return { ...f, failing };
  }

  it("next 抛错原样传播", async () => {
    const f = await throwingApproval();
    await expect(f.failing()).rejects.toThrow(/boom/);
  });

  it("next 抛错前通知已发出", async () => {
    const f = await throwingApproval();
    await f.failing().catch(() => { /* 断言已发布的通知条数 */ });
    expect(f.infos.length).toBe(3);
  });
});

describe("notifyAsk=false（组合层 entry）时不通知、不短路", () => {
  it("不短路", async () => {
    const { approval } = await approvalNotifier("off", { notifyAsk: false });
    expect(await approval({ toolName: "bash", agent: { id: "session-1" } }, async () => "allowed-once")).toBe("allowed-once");
  });

  it("notifyAsk=false 不通知", async () => {
    const { approval, infos } = await approvalNotifier("off", { notifyAsk: false });
    await approval({ toolName: "bash", agent: { id: "session-1" } }, async () => "allowed-once");
    expect(infos.length).toBe(0);
  });
});

// 免打扰紧急例外：allowKinds 中的 kind 在免打扰时段仍通知
/** 免打扰窗口动态构造（±2 分钟，绕当前时间）。 */
function quietWindowNow() {
  // 写死 "00:00"/"23:59" 假设全天覆盖，但实现是半开区间 [start, end)，
  // 23:59 这一分钟不命中，UTC 边缘必炸；now 邻近 00:00 时 start > end，
  // 天然走实现的跨午夜分支（quiet-hours.ts）。
  const hhmm = (offsetMinutes) => {
    const t = new Date(Date.now() + offsetMinutes * 60_000);
    return `${String(t.getHours()).padStart(2, "0")}:${String(t.getMinutes()).padStart(2, "0")}`;
  };
  return { enabled: true, start: hhmm(-2), end: hhmm(2) };
}

describe("免打扰紧急例外：allowKinds 含 ask 仍通知", () => {
  async function quietAllowAsk() {
    const f = await approvalNotifier("qh1", { quietHours: { ...quietWindowNow(), allowKinds: ["ask"] } });
    await f.approval({ toolName: "pwsh", agent: agentWithTitle("qh-1", "免打扰审批", { turnEnd: 1 }) }, async () => "ok");
    return f;
  }

  it("免打扰期间 ask 仍通知（紧急例外 allowKinds）", async () => {
    expect((await quietAllowAsk()).infos.length).toBe(1);
  });

  it("免打扰期间 ask 通知含 ask kind", async () => {
    expect((await quietAllowAsk()).infos[0]).toMatch(/ask/);
  });
});

describe("免打扰无 allowKinds：静默但留拦截日志", () => {
  async function quietNoAllow() {
    const f = await approvalNotifier("qh2", { quietHours: { ...quietWindowNow(), allowKinds: [] } });
    await f.approval({ toolName: "pwsh", agent: { id: "qh-2" } }, async () => "ok");
    return f;
  }

  it("无 allowKinds 时免打扰不产生实际通知", async () => {
    expect((await quietNoAllow()).infos.filter((t) => !t.includes("被免打扰拦截")).length).toBe(0);
  });

  it("被拦截仍记录日志（可核对发没发）", async () => {
    expect((await quietNoAllow()).infos.some((t) => t.includes("被免打扰拦截"))).toBeTruthy();
  });
});

