/**
 * dsh-notifier — unit：server 域 seq 计数器存储直测（#733 M1-F2）。
 *
 * createSeqStore 的实现自组合根（src/index.ts 的 loadSeq/saveSeq）**逐行等价**迁入
 * server/sse-bus.ts，本文件锁定搬迁不得改变的语义：
 * - 缺文件（ENOENT）= 首启静默回退 0，**不告警**；
 * - **合法 JSON 但值非法**（负数/小数/字符串/null/布尔/对象）→ warn「seq 计数文件损坏」+ 回退 0；
 * - **非法 JSON（解析失败）** 与其他非 ENOENT 读取失败 → warn「seq 计数文件读取失败」+ 回退 0
 *   （既有控制流：损坏文案只在 JSON.parse 成功、值校验失败时命中）；
 * - 写入为同步 tmp+rename 原子写（createSseHub 的 dispose 同步补写依赖此同步性），
 *   失败只 warn 不抛。
 *
 * 落盘全部进 mkdtempSync 隔离目录（#218 产物零污染）。
 */
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createSeqStore } from "../../src/server/interface.ts";

/** 记录告警的 fake logger。 */
function makeWarn() {
  const warns: string[] = [];
  return { warns, warn: (message: string) => warns.push(message) };
}

describe("(h) createSeqStore：load 续计数与回退语义", () => {
  let dir: string;
  let file: string;

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), "notifier-seq-store-"));
    file = join(dir, "seq.json");
  });

  afterEach(() => {
    rmSync(dir, { recursive: true, force: true });
  });

  it("缺文件（ENOENT）→ 回退 0 且不告警（首启静默）", () => {
    const log = makeWarn();
    expect(createSeqStore({ file, warn: log.warn }).load()).toBe(0);
    expect(log.warns).toEqual([]);
  });

  it("合法非负整数 → 原样续计数", () => {
    writeFileSync(file, "42", "utf8");
    const log = makeWarn();
    expect(createSeqStore({ file, warn: log.warn }).load()).toBe(42);
    expect(log.warns).toEqual([]);
  });

  it("0 → 原样返回（边界合法）", () => {
    writeFileSync(file, "0", "utf8");
    expect(createSeqStore({ file, warn: makeWarn().warn }).load()).toBe(0);
  });

  it("非法 JSON（解析失败）→ warn「读取失败」+ 回退 0（既有控制流：损坏文案只在值校验失败时命中）", () => {
    writeFileSync(file, "{not json", "utf8");
    const log = makeWarn();
    expect(createSeqStore({ file, warn: log.warn }).load()).toBe(0);
    expect(log.warns.length).toBe(1);
    expect(log.warns[0].includes("seq 计数文件读取失败")).toBe(true);
    // 逐字等价：告警文本就是 JSON.parse 的解析错误摘要，不含额外诊断前缀
    expect(log.warns[0].startsWith("dsh-notifier: seq 计数文件读取失败，回退 0：")).toBe(true);
  });

  for (const [label, raw] of [
    ["负数", "-1"],
    ["小数", "1.5"],
    ["字符串", '"7"'],
    ["null", "null"],
    ["布尔", "true"],
    ["对象", '{"seq":3}'],
  ] as const) {
    it(`合法 JSON 但值非法（${label}）→ warn「损坏」+ 回退 0`, () => {
      writeFileSync(file, raw, "utf8");
      const log = makeWarn();
      expect(createSeqStore({ file, warn: log.warn }).load()).toBe(0);
      expect(log.warns.length).toBe(1);
      // 逐字等价：文案 + 文件路径，无额外诊断文本
      expect(log.warns[0]).toBe(`dsh-notifier: seq 计数文件损坏，回退 0：${file}`);
    });
  }

  it("读取失败非 ENOENT（路径是目录）→ warn（文案含「读取失败」）+ 回退 0", () => {
    const log = makeWarn();
    // 目录路径触发 EISDIR（非 ENOENT 分支）
    expect(createSeqStore({ file: dir, warn: log.warn }).load()).toBe(0);
    expect(log.warns.length).toBe(1);
    expect(log.warns[0].includes("seq 计数文件读取失败")).toBe(true);
  });
});

describe("(i) createSeqStore：save 原子写与失败 fail-soft", () => {
  let dir: string;
  let file: string;

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), "notifier-seq-store-"));
    file = join(dir, "seq.json");
  });

  afterEach(() => {
    rmSync(dir, { recursive: true, force: true });
  });

  it("save → load 往返（同实例）", () => {
    const store = createSeqStore({ file, warn: makeWarn().warn });
    store.save(7);
    expect(store.load()).toBe(7);
  });

  it("save → load 往返（跨实例：重启续计数）", () => {
    createSeqStore({ file, warn: makeWarn().warn }).save(9);
    expect(createSeqStore({ file, warn: makeWarn().warn }).load()).toBe(9);
  });

  it("写入内容即十进制字符串（与迁出前逐字等价）", () => {
    createSeqStore({ file, warn: makeWarn().warn }).save(123);
    expect(readFileSync(file, "utf8")).toBe("123");
  });

  it("覆盖写（第二次 save 覆盖第一次，无残留）", () => {
    const store = createSeqStore({ file, warn: makeWarn().warn });
    store.save(1);
    store.save(2);
    expect(store.load()).toBe(2);
  });

  it("写入成功后目录内无 .tmp 残留（rename 原子落位）", () => {
    createSeqStore({ file, warn: makeWarn().warn }).save(5);
    expect(readdirSync(dir)).toEqual(["seq.json"]);
  });

  it("写入失败（父目录不存在）→ warn（文案含「写入失败」）且不抛", () => {
    const log = makeWarn();
    const store = createSeqStore({ file: join(dir, "missing", "seq.json"), warn: log.warn });
    expect(() => store.save(3)).not.toThrow();
    expect(log.warns.length).toBe(1);
    // 锁全等固定前缀（错误详情部分随 errno 文本变化，故用 startsWith 锚前缀）
    expect(log.warns[0].startsWith("dsh-notifier: seq 计数写入失败: ")).toBe(true);
  });
});

packages/dsh-notifier/test/unit/unit-eve.source:
/**
 * dsh-notifier — unit：event-handlers 核心判定直测（红测先行）。
 *
 * 现状 resolveTurnEvidence（push 优先/快照兜底/stale 冻结/rememberedTurn）是
 * 模块私有函数（event-handlers.ts），行为只有 e2e 黑盒覆盖——失败定位只能靠
 * 黑盒。本文件导出并锁定判定矩阵基线；adjudicate 拆分时是
 * 行为对等判别网。
 */
import { beforeEach, describe, expect, it } from "vitest";
import { resolveTurnEvidence } from "../../src/events/interface.ts";
import type { AgentState } from "../../src/events/interface.ts";
import { agentWithTitle } from "../helpers.ts";

type EvidenceAgent = ReturnType<typeof agentWithTitle>;
type EventStreamEnds = Parameters<typeof resolveTurnEvidence>[2];
type Evidence = ReturnType<typeof resolveTurnEvidence>;

function run(agent: EvidenceAgent, state: AgentState, streamEnds: EventStreamEnds = new Map()) {
  return resolveTurnEvidence(agent, state, streamEnds);
}

describe("1：push 优先（session/event 推送条目胜于快照）", () => {
  let ev: Evidence;

  beforeEach(() => {
    const agent = agentWithTitle("a1", "任务X", { turnEnd: 5 });
    const state = { runningSeen: false, startedAt: 0, runningBaseline: { turn: 3, kind: "completed" } };
    ev = run(agent, state, new Map([["a1", { turn: 6, kind: "completed" }]]));
  });

  it("push 条目取回", () => {
    expect(ev.pushed!.turn).toBe(6);
  });

  it("证据源 = push", () => {
    expect(ev.evidenceSource).toBe("push");
  });

  it("best = push（胜过快照 5）", () => {
    expect(ev.best!.turn).toBe(6);
  });

  it("push turn6 > 记忆 undefined → 新 closure", () => {
    expect(ev.hasNewEnd).toBe(true);
  });

  it("push 命中时不读快照（快照仅兜底，防御侧零 IO）", () => {
    expect(ev.snapshot).toBeUndefined();
  });
});

describe("2：快照兜底（无 push、无基线 → 快照为准）", () => {
  let ev: Evidence;

  beforeEach(() => {
    const agent = agentWithTitle("a2", "任务Y", { turnEnd: 4 });
    const state = { runningSeen: false, startedAt: 0, runningBaseline: undefined };
    ev = run(agent, state);
  });

  it("无 push", () => {
    expect(ev.pushed).toBeUndefined();
  });

  it("证据源 = 快照兜底", () => {
    expect(ev.evidenceSource).toBe("快照兜底");
  });

  it("best = 快照 turn4", () => {
    expect(ev.best!.turn).toBe(4);
  });

  it("快照 turn4 > 记忆 undefined → 新 closure", () => {
    expect(ev.hasNewEnd).toBe(true);
  });
});

describe("3：stale 冻结（快照 ≤ running 基线 → abort-early 陈旧，冻结不误报）", () => {
  let ev: Evidence;

  beforeEach(() => {
    const agent = agentWithTitle("a3", "任务Z", { turnEnd: 3 });
    const state = { runningSeen: false, startedAt: 0, runningBaseline: { turn: 3, kind: "completed" } };
    ev = run(agent, state);
  });

  it("证据源 = 快照冻结", () => {
    expect(ev.evidenceSource).toBe("快照冻结");
  });

  it("best 为空（陈旧快照不推进）", () => {
    expect(ev.best).toBeUndefined();
  });

  it("不当作新 closure", () => {
    expect(ev.hasNewEnd).toBe(false);
  });

  it("snapshot 保留供日志", () => {
    expect(ev.snapshot!.turn).toBe(3);
  });
});

describe("4：rememberedTurn 去重（hasNewEnd = best.turn > 记忆）", () => {
  let agent: EvidenceAgent;

  beforeEach(() => {
    agent = agentWithTitle("a4", "任务W", { turnEnd: 5 });
  });

  it("best.turn 5 = 记忆 5 → 不算新 closure", () => {
    const base = { runningSeen: false, startedAt: 0, runningBaseline: undefined };
    expect(run(agent, { ...base, lastEndedTurn: 5 }).hasNewEnd).toBe(false);
  });

  it("best.turn 5 > 记忆 4 → 新 closure", () => {
    const base = { runningSeen: false, startedAt: 0, runningBaseline: undefined };
    expect(run(agent, { ...base, lastEndedTurn: 4 }).hasNewEnd).toBe(true);
  });

  it("记忆为空 → 首轮即新 closure", () => {
    expect(run(agent, { runningSeen: false, startedAt: 0, runningBaseline: undefined }).hasNewEnd).toBe(true);
  });
});

describe("5：无证据（pushed 与快照皆无 → 保守静默）", () => {
  let ev: Evidence;

  beforeEach(() => {
    const agent = agentWithTitle("a5", undefined); // 无 turn/end 事件
    ev = run(agent, { runningSeen: false, startedAt: 0 });
  });

  it("best 为空", () => {
    expect(ev.best).toBeUndefined();
  });

  it("证据源 = 无", () => {
    expect(ev.evidenceSource).toBe("无");
  });

  it("不当作新 closure（S1：无证据静默）", () => {
    expect(ev.hasNewEnd).toBe(false);
  });
});
